    var tail = (det.trading_name ? '\n' + det.trading_name : '') + (phone ? (det.trading_name ? ' · ' : '\n') + phone : ''), cap = function (s) { return s.charAt(0).toUpperCase() + s.slice(1); }, body, subject;
